        /// <summary>
        /// For inline array structs, element access expressions and conversions to
        /// <see cref="System.Span{T}"/>/<see cref="System.ReadOnlySpan{T}"/> use built-in language mechanisms
        /// rather than any custom indexers, 'Slice' methods, or conversion operators declared on the struct.
        /// Warn the developer that such members will not be used.
        /// </summary>
        private void CheckInlineArrayMembersNotUsed(BindingDiagnosticBag diagnostics)
        {
            var elementType = TryGetInlineArrayElementField()?.Type;

            foreach (Symbol member in GetMembers())
            {
                switch (member)
                {
                    case PropertySymbol { IsIndexer: true } indexer
                        when !IsRefLikeType
                             && indexer.ExplicitInterfaceImplementations.IsEmpty
                             && indexer.ParameterCount == 1
                             && IsInlineArrayIndexerParameterType(indexer.Parameters[0].Type):
                        diagnostics.Add(ErrorCode.WRN_InlineArrayIndexerNotUsed, indexer.GetFirstLocation());
                        break;

                    case MethodSymbol { MethodKind: MethodKind.Ordinary, Name: "Slice" } sliceMethod
                        when sliceMethod.ExplicitInterfaceImplementations.IsEmpty
                             && sliceMethod.ParameterCount == 2
                             && sliceMethod.Parameters[0].Type.SpecialType == SpecialType.System_Int32
                             && sliceMethod.Parameters[1].Type.SpecialType == SpecialType.System_Int32
                             && !sliceMethod.ReturnsVoid:
                        diagnostics.Add(ErrorCode.WRN_InlineArraySliceNotUsed, sliceMethod.GetFirstLocation());
                        break;

                    case MethodSymbol { MethodKind: MethodKind.Conversion } conversion
                        when elementType is not null
                             && IsInlineArrayBypassedSpanConversion(conversion, elementType):
                        diagnostics.Add(ErrorCode.WRN_InlineArrayConversionOperatorNotUsed, conversion.GetFirstLocation());
                        break;
                }
            }
        }

        private bool IsInlineArrayIndexerParameterType(TypeSymbol type)
        {
            return type.SpecialType == SpecialType.System_Int32
                || type.Equals(DeclaringCompilation.GetWellKnownType(WellKnownType.System_Index), TypeCompareKind.AllIgnoreOptions)
                || type.Equals(DeclaringCompilation.GetWellKnownType(WellKnownType.System_Range), TypeCompareKind.AllIgnoreOptions);
        }

        private bool IsInlineArrayBypassedSpanConversion(MethodSymbol conversion, TypeSymbol elementType)
        {
            if (conversion.ParameterCount != 1)
            {
                return false;
            }

            // The built-in conversion only applies to the (non-nullable) inline array value itself,
            // so a conversion whose source is a nullable variant of the declaring type is still usable.
            if (conversion.Parameters[0].Type.IsNullableType())
            {
                return false;
            }

            if (conversion.ReturnType is NamedTypeSymbol { Arity: 1 } returnType
                && (returnType.OriginalDefinition.Equals(DeclaringCompilation.GetWellKnownType(WellKnownType.System_Span_T), TypeCompareKind.AllIgnoreOptions)
                    || returnType.OriginalDefinition.Equals(DeclaringCompilation.GetWellKnownType(WellKnownType.System_ReadOnlySpan_T), TypeCompareKind.AllIgnoreOptions)))
            {
                return returnType.TypeArgumentsWithAnnotationsNoUseSiteDiagnostics[0].Type.Equals(elementType, TypeCompareKind.AllIgnoreOptions);
            }

            return false;
        }
    }
